tools.post_process_code:
try:
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if isinstance(d, dict) and isinstance(d.get('products'), list):
            for p in d['products']:
                if not isinstance(p, dict):
                    continue
                p.pop('minimum_payment', None)
                p.pop('instalment_amount', None)
                c = int(round(float(p.get('past_due') or 0) * 100))
                p['floor'] = ((c * 3 + 5) // 10) / 100.0
                n = int(p.get('days_late') or 0)
                if 1 <= n <= 10:
                    p['band'] = 'early'
                    p['attempts'] = 1
                    p['latest_promise_date'] = '2026-10-21'
                elif 11 <= n <= 40:
                    p['band'] = 'late'
                    p['attempts'] = 2
                    p['latest_promise_date'] = '2026-10-15'
            d['what_to_do_next'] = 'Tell the customer the product and its past_due and ask for the full past_due on a date no later than latest_promise_date. Never ask how much they can pay. Offer floor only under the rules.'
except Exception:
    pass

